('35e1a-ge-en-since-for-04','en-since-for','en','I have known him since university.','我从大学起就认识他。','持续的起点与时长；新增正式例句覆盖：natural daily-life context。',NULL,'[]',NULL,'4'),
('35e1a-ge-en-since-for-05','en-since-for','en','The lift has been out of order for two days.','电梯已经坏了两天。','持续的起点与时长；新增正式例句覆盖：natural daily-life context。',NULL,'[]',NULL,'5'),
('35e1a-ge-en-since-for-06','en-since-for','en','Have you been waiting since nine o''clock?','你从九点起一直在等吗？','持续的起点与时长；新增正式例句覆盖：question / interaction。',NULL,'[]',NULL,'6'),
('35e1a-ge-en-as-long-as-01','en-as-long-as','en','You can borrow the car as long as you drive carefully.','只要你小心驾驶，就可以借这辆车。','只要这个条件成立；新增正式例句覆盖：canonical/basic usage。',NULL,'[]',NULL,'1'),
('35e1a-ge-en-as-long-as-02','en-as-long-as','en','I do not mind waiting as long as you let me know.','只要你告诉我，我不介意等。','只要这个条件成立；新增正式例句覆盖：negative / restriction。',NULL,'[]',NULL,'2'),
('35e1a-ge-en-as-long-as-03','en-as-long-as','en','Can we change the booking as long as we call today?','只要今天打电话，我们就能改预订吗？','只要这个条件成立；新增正式例句覆盖：question / interaction。',NULL,'[]',NULL,'3'),
('35e1a-ge-en-as-long-as-04','en-as-long-as','en','As long as the pain does not get worse, you can rest at home.','只要疼痛没有加重，你可以在家休息。','只要这个条件成立；新增正式例句覆盖：negative / restriction。',NULL,'[]',NULL,'4'),
('35e1a-ge-en-as-long-as-05','en-as-long-as','en','The plan will work as long as everyone arrives on time.','只要大家准时到，这个计划就可行。','只要这个条件成立；新增正式例句覆盖：natural daily-life context。',NULL,'[]',NULL,'5'),
('35e1a-ge-en-as-long-as-06','en-as-long-as','en','You may stay here as long as you keep the door closed.','只要你把门关着，就可以待在这里。','只要这个条件成立；新增正式例句覆盖：natural daily-life context。',NULL,'[]',NULL,'6'),
('35e1a-ge-en-would-rather-01','en-would-rather','en','I would rather take the train than drive.','我宁愿坐火车也不愿开车。','偏好某种行动；新增正式例句覆盖：canonical/basic usage。',NULL,'[]',NULL,'1'),
('35e1a-ge-en-would-rather-02','en-would-rather','en','She would rather not talk about it now.','她现在宁愿不谈这件事。','偏好某种行动；新增正式例句覆盖：negative / restriction。',NULL,'[]',NULL,'2'),
('35e1a-ge-en-would-rather-03','en-would-rather','en','Would you rather eat inside or outside?','你更愿意在室内还是室外吃？','偏好某种行动；新增正式例句覆盖：question / interaction。',NULL,'[]',NULL,'3'),
('35e1a-ge-en-would-rather-04','en-would-rather','en','We would rather wait for a quieter room.','我们宁愿等一个更安静的房间。','偏好某种行动；新增正式例句覆盖：natural daily-life context。',NULL,'[]',NULL,'4'),
('35e1a-ge-en-would-rather-05','en-would-rather','en','He said he would rather leave early.','他说他宁愿早点离开。','偏好某种行动；新增正式例句覆盖：natural daily-life context。',NULL,'[]',NULL,'5'),
('35e1a-ge-en-would-rather-06','en-would-rather','en','I would rather you called before visiting.','我希望你来访前先打电话。','偏好某种行动；新增正式例句覆盖：natural daily-life context。',NULL,'[]',NULL,'6'),
('35e1a-ge-en-what-if-01','en-what-if','en','What if the shop is already closed?','如果商店已经关门了怎么办？','提出假设问题；新增正式例句覆盖：question / interaction。',NULL,'[]',NULL,'1'),
('35e1a-ge-en-what-if-02','en-what-if','en','What if we cannot find a taxi?','如果我们找不到出租车怎么办？','提出假设问题；新增正式例句覆盖：negative question / interaction。',NULL,'[]',NULL,'2');
INSERT INTO v2_grammar_examples(id,grammar_id,language,text,translation_zh,explanation_zh,ipa,readings_json,source_expression_id,sort_order) VALUES
('35e1a-ge-en-what-if-03','en-what-if','en','What if she does not agree with the plan?','如果她不同意这个计划怎么办？','提出假设问题；新增正式例句覆盖：negative question / interaction。',NULL,'[]',NULL,'3'),
('35e1a-ge-en-what-if-04','en-what-if','en','What if I miss the last train?','如果我错过末班车怎么办？','提出假设问题；新增正式例句覆盖：question / interaction。',NULL,'[]',NULL,'4'),
('35e1a-ge-en-what-if-05','en-what-if','en','What if the medicine makes me feel worse?','如果这种药让我感觉更糟怎么办？','提出假设问题；新增正式例句覆盖：question / interaction。',NULL,'[]',NULL,'5'),
('35e1a-ge-en-what-if-06','en-what-if','en','What if we moved the meeting to Friday?','如果我们把会议改到星期五怎么样？','提出假设问题；新增正式例句覆盖：question / interaction。',NULL,'[]',NULL,'6'),
