('35e1a-ge-ja-hodo-approx-03','ja-hodo-approx','ja','この箱には米が五キロほど入っています。','这个箱子里大约装了五公斤大米。','大约的数量；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"この箱には米が五キロほど入っています。","reading":"このはこにはこめがごきろほどはいっています。"}]',NULL,'3'),
('35e1a-ge-ja-hodo-approx-04','ja-hodo-approx','ja','あと一時間ほど待てますか。','还能等大约一个小时吗？','大约的数量；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"あと一時間ほど待てますか。","reading":"あといちじかんほどまてますか。"}]',NULL,'4'),
('35e1a-ge-ja-hodo-approx-05','ja-hodo-approx','ja','週に二回ほど運動します。','每周大约运动两次。','大约的数量；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"週に二回ほど運動します。","reading":"しゅうににかいほどうんどうします。"}]',NULL,'5'),
('35e1a-ge-ja-hodo-approx-06','ja-hodo-approx','ja','昼休みは四十分ほどです。','午休大约四十分钟。','大约的数量；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"昼休みは四十分ほどです。","reading":"ひるやすみはよんじゅっぷんほどです。"}]',NULL,'6'),
('35e1a-ge-ja-hodo-approx-07','ja-hodo-approx','ja','修理には二日ほどかかるそうです。','听说维修大约需要两天。','大约的数量；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"修理には二日ほどかかるそうです。","reading":"しゅうりにはふつかほどかかるそうです。"}]',NULL,'7'),
('35e1a-ge-ja-dake-01','ja-dake','ja','今日は水だけ飲みました。','今天只喝了水。','限定范围；新增正式例句覆盖：canonical/basic usage。',NULL,'[{"text":"今日は水だけ飲みました。","reading":"きょうはみずだけのみました。"}]',NULL,'1'),
('35e1a-ge-ja-dake-02','ja-dake','ja','必要な物だけ買いましょう。','只买需要的东西吧。','限定范围；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"必要な物だけ買いましょう。","reading":"ひつようなものだけかいましょう。"}]',NULL,'2'),
('35e1a-ge-ja-dake-03','ja-dake','ja','私は説明を聞いただけです。','我只是听了说明。','限定范围；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"私は説明を聞いただけです。","reading":"わたしはせつめいをきいただけです。"}]',NULL,'3'),
('35e1a-ge-ja-dake-04','ja-dake','ja','この部屋には椅子が一つだけあります。','这个房间里只有一把椅子。','限定范围；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"この部屋には椅子が一つだけあります。","reading":"このへやにはいすがひとつだけあります。"}]',NULL,'4'),
('35e1a-ge-ja-dake-05','ja-dake','ja','名前を書くだけで大丈夫です。','只写名字就可以。','限定范围；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"名前を書くだけで大丈夫です。","reading":"なまえをかくだけでだいじょうぶです。"}]',NULL,'5'),
('35e1a-ge-ja-dake-06','ja-dake','ja','一日だけ予定を延ばせますか。','可以只把日程延后一天吗？','限定范围；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"一日だけ予定を延ばせますか。","reading":"いちにちだけよていをのばせますか。"}]',NULL,'6'),
('35e1a-ge-ja-dake-07','ja-dake','ja','彼だけが答えを知っています。','只有他知道答案。','限定范围；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"彼だけが答えを知っています。","reading":"かれだけがこたえをしっています。"}]',NULL,'7'),
('35e1a-ge-ja-duration-01','ja-duration','ja','空港まで一時間かかります。','到机场需要一个小时。','所需时间；新增正式例句覆盖：canonical/basic usage。',NULL,'[{"text":"空港まで一時間かかります。","reading":"くうこうまでいちじかんかかります。"}]',NULL,'1'),
('35e1a-ge-ja-duration-02','ja-duration','ja','この料理は作るのに三十分かかります。','做这道菜需要三十分钟。','所需时间；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"この料理は作るのに三十分かかります。","reading":"このりょうりはつくるのにさんじゅっぷんかかります。"}]',NULL,'2'),
('35e1a-ge-ja-duration-03','ja-duration','ja','修理には何日かかりますか。','维修需要几天？','所需时间；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"修理には何日かかりますか。","reading":"しゅうりにはなんにちかかりますか。"}]',NULL,'3'),
('35e1a-ge-ja-duration-04','ja-duration','ja','昨日は帰るのに二時間かかりました。','昨天回家花了两个小时。','所需时间；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"昨日は帰るのに二時間かかりました。","reading":"きのうはかえるのににじかんかかりました。"}]',NULL,'4'),
('35e1a-ge-ja-duration-05','ja-duration','ja','修理にはあまり時間がかかりません。','维修不太花时间。','所需时间；新增正式例句覆盖：negative / restriction。',NULL,'[{"text":"修理にはあまり時間がかかりません。","reading":"しゅうりにはあまりじかんがかかりません。"}]',NULL,'5'),
('35e1a-ge-ja-duration-06','ja-duration','ja','手続きはあと十分ほどかかります。','手续还需要大约十分钟。','所需时间；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"手続きはあと十分ほどかかります。","reading":"てつづきはあとじゅっぷんほどかかります。"}]',NULL,'6'),
('35e1a-ge-ja-duration-07','ja-duration','ja','混んでいると、もっと時間がかかります。','拥挤时会花更长时间。','所需时间；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"混んでいると、もっと時間がかかります。","reading":"こんでいると、もっとじかんがかかります。"}]',NULL,'7'),
('35e1a-ge-ja-ni-naru-01','ja-ni-naru','ja','来月、大学生になります。','下个月就成为大学生了。','变成某种状态；新增正式例句覆盖：canonical/basic usage。',NULL,'[{"text":"来月、大学生になります。","reading":"らいげつ、だいがくせいになります。"}]',NULL,'1'),
('35e1a-ge-ja-ni-naru-02','ja-ni-naru','ja','夜になると、この道は静かになります。','到了晚上，这条路会变安静。','变成某种状态；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"夜になると、この道は静かになります。","reading":"よるになると、このみちはしずかになります。"}]',NULL,'2'),
('35e1a-ge-ja-ni-naru-03','ja-ni-naru','ja','部屋がきれいになりました。','房间变干净了。','变成某种状态；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"部屋がきれいになりました。","reading":"へやがきれいになりました。"}]',NULL,'3'),
('35e1a-ge-ja-ni-naru-04','ja-ni-naru','ja','会議は午後三時からになります。','会议改为下午三点开始。','变成某种状态；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"会議は午後三時からになります。","reading":"かいぎはごごさんじからになります。"}]',NULL,'4'),
('35e1a-ge-ja-ni-naru-05','ja-ni-naru','ja','この薬を飲むと眠くなることがあります。','吃这种药有时会犯困。','变成某种状态；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"この薬を飲むと眠くなることがあります。","reading":"このくすりをのむとねむくなることがあります。"}]',NULL,'5'),
('35e1a-ge-ja-ni-naru-06','ja-ni-naru','ja','練習すれば、もっと上手になります。','练习的话会变得更熟练。','变成某种状态；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"練習すれば、もっと上手になります。","reading":"れんしゅうすれば、もっとじょうずになります。"}]',NULL,'6'),
('35e1a-ge-ja-ni-naru-07','ja-ni-naru','ja','予定は来週に変更になりました。','日程改到下周了。','变成某种状态；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"予定は来週に変更になりました。","reading":"よていはらいしゅうにへんこうになりました。"}]',NULL,'7'),
('35e1a-ge-ja-te-iru-01','ja-te-iru','ja','今、駅で電車を待っています。','现在正在车站等电车。','描述进行、结果状态或到目前的完成状况；新增正式例句覆盖：canonical/basic usage。',NULL,'[{"text":"今、駅で電車を待っています。","reading":"いま、えきででんしゃをまっています。"}]',NULL,'1'),
('35e1a-ge-ja-te-iru-02','ja-te-iru','ja','姉は東京に住んでいます。','姐姐住在东京。','描述进行、结果状态或到目前的完成状况；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"姉は東京に住んでいます。","reading":"あねはとうきょうにすんでいます。"}]',NULL,'2'),
('35e1a-ge-ja-te-iru-03','ja-te-iru','ja','窓が開いています。','窗户开着。','描述进行、结果状态或到目前的完成状况；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"窓が開いています。","reading":"まどがあいています。"}]',NULL,'3'),
('35e1a-ge-ja-te-iru-04','ja-te-iru','ja','今日は車を使っていません。','今天没有在用车。','描述进行、结果状态或到目前的完成状况；新增正式例句覆盖：negative / restriction。',NULL,'[{"text":"今日は車を使っていません。","reading":"きょうはくるまをつかっていません。"}]',NULL,'4'),
('35e1a-ge-ja-te-iru-05','ja-te-iru','ja','何を読んでいますか。','你在读什么？','描述进行、结果状态或到目前的完成状况；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"何を読んでいますか。","reading":"なにをよんでいますか。"}]',NULL,'5'),
('35e1a-ge-ja-te-iru-06','ja-te-iru','ja','この店は十年前から営業しています。','这家店从十年前起一直营业。','描述进行、结果状态或到目前的完成状况；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"この店は十年前から営業しています。","reading":"このみせはじゅうねんまえからえいぎょうしています。"}]',NULL,'6'),
('35e1a-ge-ja-te-iru-07','ja-te-iru','ja','父は今、夕食を作っています。','爸爸现在正在做晚饭。','描述进行、结果状态或到目前的完成状况；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"父は今、夕食を作っています。","reading":"ちちはいま、ゆうしょくをつくっています。"}]',NULL,'7'),
('35e1a-ge-ja-tsumori-01','ja-tsumori','ja','来年、日本へ行くつもりです。','我打算明年去日本。','表达打算；新增正式例句覆盖：canonical/basic usage。',NULL,'[{"text":"来年、日本へ行くつもりです。","reading":"らいねん、にほんへいくつもりです。"}]',NULL,'1'),
('35e1a-ge-ja-tsumori-02','ja-tsumori','ja','今日は外出しないつもりです。','今天打算不出门。','表达打算；新增正式例句覆盖：negative / restriction。',NULL,'[{"text":"今日は外出しないつもりです。","reading":"きょうはがいしゅつしないつもりです。"}]',NULL,'2'),
('35e1a-ge-ja-tsumori-03','ja-tsumori','ja','何時に帰るつもりですか。','你打算几点回去？','表达打算；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"何時に帰るつもりですか。","reading":"なんじにかえるつもりですか。"}]',NULL,'3'),
('35e1a-ge-ja-tsumori-04','ja-tsumori','ja','週末に部屋を掃除するつもりでした。','我原打算周末打扫房间。','表达打算；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"週末に部屋を掃除するつもりでした。","reading":"しゅうまつにへやをそうじするつもりでした。"}]',NULL,'4'),
('35e1a-ge-ja-tsumori-05','ja-tsumori','ja','そんなことを言うつもりはありませんでした。','我没有打算说那样的话。','表达打算；新增正式例句覆盖：negative / restriction。',NULL,'[{"text":"そんなことを言うつもりはありませんでした。","reading":"そんなことをいうつもりはありませんでした。"}]',NULL,'5'),
('35e1a-ge-ja-tsumori-06','ja-tsumori','ja','卒業後は働くつもりです。','毕业后打算工作。','表达打算；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"卒業後は働くつもりです。","reading":"そつぎょうごははたらくつもりです。"}]',NULL,'6');
INSERT INTO v2_grammar_examples(id,grammar_id,language,text,translation_zh,explanation_zh,ipa,readings_json,source_expression_id,sort_order) VALUES
('35e1a-ge-ja-tsumori-07','ja-tsumori','ja','この計画を変えるつもりはありません。','我不打算改变这个计划。','表达打算；新增正式例句覆盖：negative / restriction。',NULL,'[{"text":"この計画を変えるつもりはありません。","reading":"このけいかくをかえるつもりはありません。"}]',NULL,'7'),
('35e1a-ge-ja-kamoshirenai-01','ja-kamoshirenai','ja','明日は雪になるかもしれません。','明天可能会下雪。','表达推测；新增正式例句覆盖：negative / restriction。',NULL,'[{"text":"明日は雪になるかもしれません。","reading":"あすはゆきになるかもしれません。"}]',NULL,'1'),
('35e1a-ge-ja-kamoshirenai-02','ja-kamoshirenai','ja','彼は今日は来ないかもしれない。','他今天可能不来。','表达推测；新增正式例句覆盖：negative / restriction。',NULL,'[{"text":"彼は今日は来ないかもしれない。","reading":"かれはきょうはこないかもしれない。"}]',NULL,'2'),
('35e1a-ge-ja-kamoshirenai-03','ja-kamoshirenai','ja','午後は雨が降るかもしれません。','下午可能会下雨。','表达推测；新增正式例句覆盖：negative / restriction。',NULL,'[{"text":"午後は雨が降るかもしれません。","reading":"ごごはあめがふるかもしれません。"}]',NULL,'3'),
('35e1a-ge-ja-kamoshirenai-04','ja-kamoshirenai','ja','この薬は眠くなるかもしれません。','这种药可能会让人犯困。','表达推测；新增正式例句覆盖：negative / restriction。',NULL,'[{"text":"この薬は眠くなるかもしれません。","reading":"このくすりはねむくなるかもしれません。"}]',NULL,'4'),
('35e1a-ge-ja-kamoshirenai-05','ja-kamoshirenai','ja','予約を変更できるかもしれません。','预约或许可以更改。','表达推测；新增正式例句覆盖：negative / restriction。',NULL,'[{"text":"予約を変更できるかもしれません。","reading":"よやくをへんこうできるかもしれません。"}]',NULL,'5'),
('35e1a-ge-ja-kamoshirenai-06','ja-kamoshirenai','ja','それは誤解だったかもしれない。','那可能是误会。','表达推测；新增正式例句覆盖：negative / restriction。',NULL,'[{"text":"それは誤解だったかもしれない。","reading":"それはごかいだったかもしれない。"}]',NULL,'6'),
('35e1a-ge-ja-kamoshirenai-07','ja-kamoshirenai','ja','駅よりバス停のほうが近いかもしれません。','公交车站可能比火车站更近。','表达推测；新增正式例句覆盖：negative / restriction。',NULL,'[{"text":"駅よりバス停のほうが近いかもしれません。","reading":"えきよりばすていのほうがちかいかもしれません。"}]',NULL,'7'),
('35e1a-ge-ja-sou-01','ja-sou','ja','この料理はおいしそうです。','这道菜看起来很好吃。','表达外观上的推测；新增正式例句覆盖：canonical/basic usage。',NULL,'[{"text":"この料理はおいしそうです。","reading":"このりょうりはおいしそうです。"}]',NULL,'1'),
('35e1a-ge-ja-sou-02','ja-sou','ja','今日は雨が降らなさそうです。','今天看起来不会下雨。','表达外观上的推测；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"今日は雨が降らなさそうです。","reading":"きょうはあめがふらなさそうです。"}]',NULL,'2'),
('35e1a-ge-ja-sou-03','ja-sou','ja','そのかばんは重そうですか。','那个包看起来重吗？','表达外观上的推测；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"そのかばんは重そうですか。","reading":"そのかばんはおもそうですか。"}]',NULL,'3'),
('35e1a-ge-ja-sou-04','ja-sou','ja','電車がすぐ来そうです。','电车看起来马上要来了。','表达外观上的推测；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"電車がすぐ来そうです。","reading":"でんしゃがすぐきそうです。"}]',NULL,'4'),
('35e1a-ge-ja-sou-05','ja-sou','ja','彼は少し疲れていそうです。','他看起来有点累。','表达外观上的推测；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"彼は少し疲れていそうです。","reading":"かれはすこしつかれていそうです。"}]',NULL,'5'),
('35e1a-ge-ja-sou-06','ja-sou','ja','この仕事は時間がかかりそうです。','这项工作看起来会花时间。','表达外观上的推测；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"この仕事は時間がかかりそうです。","reading":"このしごとはじかんがかかりそうです。"}]',NULL,'6'),
('35e1a-ge-ja-sou-07','ja-sou','ja','その店はもう閉まりそうです。','那家店看起来快关门了。','表达外观上的推测；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"その店はもう閉まりそうです。","reading":"そのみせはもうしまりそうです。"}]',NULL,'7'),
('35e1a-ge-ja-hou-ga-ii-01','ja-hou-ga-ii','ja','熱があるなら、今日は休んだほうがいいです。','如果发烧，今天最好休息。','建议；新增正式例句覆盖：canonical/basic usage。',NULL,'[{"text":"熱があるなら、今日は休んだほうがいいです。","reading":"ねつがあるなら、きょうはやすんだほうがいいです。"}]',NULL,'1'),
('35e1a-ge-ja-hou-ga-ii-02','ja-hou-ga-ii','ja','この道は夜一人で歩かないほうがいいです。','这条路晚上最好不要一个人走。','建议；新增正式例句覆盖：negative / restriction。',NULL,'[{"text":"この道は夜一人で歩かないほうがいいです。","reading":"このみちはよるひとりであるかないほうがいいです。"}]',NULL,'2'),
('35e1a-ge-ja-hou-ga-ii-03','ja-hou-ga-ii','ja','先に予約したほうがいいですか。','最好事先预约吗？','建议；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"先に予約したほうがいいですか。","reading":"さきによやくしたほうがいいですか。"}]',NULL,'3'),
('35e1a-ge-ja-hou-ga-ii-04','ja-hou-ga-ii','ja','大事な書類はコピーしておいたほうがいいです。','重要文件最好事先复印。','建议；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"大事な書類はコピーしておいたほうがいいです。","reading":"だいじなしょるいはこぴーしておいたほうがいいです。"}]',NULL,'4'),
('35e1a-ge-ja-hou-ga-ii-05','ja-hou-ga-ii','ja','そんなに心配しないほうがいいですよ。','最好不要那么担心。','建议；新增正式例句覆盖：negative / restriction。',NULL,'[{"text":"そんなに心配しないほうがいいですよ。","reading":"そんなにしんぱいしないほうがいいですよ。"}]',NULL,'5'),
('35e1a-ge-ja-hou-ga-ii-06','ja-hou-ga-ii','ja','電車よりバスで行ったほうがいいと思います。','我觉得最好坐公交车去，而不是坐电车。','建议；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"電車よりバスで行ったほうがいいと思います。","reading":"でんしゃよりばすでいったほうがいいとおもいます。"}]',NULL,'6'),
('35e1a-ge-ja-hou-ga-ii-07','ja-hou-ga-ii','ja','わからないときは、すぐ聞いたほうがいいです。','不懂的时候最好马上问。','建议；新增正式例句覆盖：negative / restriction。',NULL,'[{"text":"わからないときは、すぐ聞いたほうがいいです。","reading":"わからないときは、すぐきいたほうがいいです。"}]',NULL,'7'),
('35e1a-ge-ja-te-morau-01','ja-te-morau','ja','友達に駅まで送ってもらいました。','朋友送我到了车站。','请求受惠；新增正式例句覆盖：canonical/basic usage。',NULL,'[{"text":"友達に駅まで送ってもらいました。","reading":"ともだちにえきまでおくってもらいました。"}]',NULL,'1'),
('35e1a-ge-ja-te-morau-02','ja-te-morau','ja','ここに名前を書いてもらえますか。','能请你在这里写名字吗？','请求受惠；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"ここに名前を書いてもらえますか。","reading":"ここになまえをかいてもらえますか。"}]',NULL,'2'),
('35e1a-ge-ja-te-morau-03','ja-te-morau','ja','先生に文章を直してもらいました。','老师帮我修改了文章。','请求受惠；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"先生に文章を直してもらいました。","reading":"せんせいにぶんしょうをなおしてもらいました。"}]',NULL,'3'),
('35e1a-ge-ja-te-morau-04','ja-te-morau','ja','少し待ってもらえませんか。','能请你稍等一下吗？','请求受惠；新增正式例句覆盖：negative / restriction。',NULL,'[{"text":"少し待ってもらえませんか。","reading":"すこしまってもらえませんか。"}]',NULL,'4'),
('35e1a-ge-ja-te-morau-05','ja-te-morau','ja','店員さんに別のサイズを持ってきてもらいました。','店员给我拿来了别的尺码。','请求受惠；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"店員さんに別のサイズを持ってきてもらいました。","reading":"てんいんさんにべつのさいずをもってきてもらいました。"}]',NULL,'5'),
('35e1a-ge-ja-te-morau-06','ja-te-morau','ja','誰に手伝ってもらいましたか。','你请谁帮忙了？','请求受惠；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"誰に手伝ってもらいましたか。","reading":"だれにてつだってもらいましたか。"}]',NULL,'6'),
('35e1a-ge-ja-te-morau-07','ja-te-morau','ja','明日の午後に変更してもらえますか。','能请你改到明天下午吗？','请求受惠；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"明日の午後に変更してもらえますか。","reading":"あすのごごにへんこうしてもらえますか。"}]',NULL,'7'),
('35e1a-ge-ja-nara-01','ja-nara','ja','電車で行くなら、この駅で乗り換えてください。','如果坐电车去，请在这个车站换乘。','承接条件；新增正式例句覆盖：canonical/basic usage。',NULL,'[{"text":"電車で行くなら、この駅で乗り換えてください。","reading":"でんしゃでいくなら、このえきでのりかえてください。"}]',NULL,'1'),
('35e1a-ge-ja-nara-02','ja-nara','ja','辛い物が苦手なら、こちらの料理がおすすめです。','如果不喜欢辣的，推荐这道菜。','承接条件；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"辛い物が苦手なら、こちらの料理がおすすめです。","reading":"からいものがにがてなら、こちらのりょうりがおすすめです。"}]',NULL,'2'),
('35e1a-ge-ja-nara-03','ja-nara','ja','明日が無理なら、金曜日はどうですか。','如果明天不行，星期五怎么样？','承接条件；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"明日が無理なら、金曜日はどうですか。","reading":"あすがむりなら、きんようびはどうですか。"}]',NULL,'3'),
('35e1a-ge-ja-nara-04','ja-nara','ja','返品するなら、レシートを捨てないでください。','如果要退货，请不要丢掉收据。','承接条件；新增正式例句覆盖：negative / restriction。',NULL,'[{"text":"返品するなら、レシートを捨てないでください。","reading":"へんぴんするなら、れしーとをすてないでください。"}]',NULL,'4'),
('35e1a-ge-ja-nara-05','ja-nara','ja','静かな部屋なら、三階にあります。','如果要安静的房间，三楼有。','承接条件；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"静かな部屋なら、三階にあります。","reading":"しずかなへやなら、さんがいにあります。"}]',NULL,'5'),
('35e1a-ge-ja-nara-06','ja-nara','ja','田中さんも参加するなら、私も行きます。','如果田中也参加，我也去。','承接条件；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"田中さんも参加するなら、私も行きます。","reading":"たなかさんもさんかするなら、わたしもいきます。"}]',NULL,'6'),
('35e1a-ge-ja-nara-07','ja-nara','ja','わからないことがあるなら、今聞いてください。','如果有不懂的地方，现在请问。','承接条件；新增正式例句覆盖：negative / restriction。',NULL,'[{"text":"わからないことがあるなら、今聞いてください。","reading":"わからないことがあるなら、いまきいてください。"}]',NULL,'7'),
('35e1a-ge-ja-tara-01','ja-tara','ja','駅に着いたら、電話してください。','到了车站后请打电话。','条件或完成后；新增正式例句覆盖：canonical/basic usage。',NULL,'[{"text":"駅に着いたら、電話してください。","reading":"えきについたら、でんわしてください。"}]',NULL,'1'),
('35e1a-ge-ja-tara-02','ja-tara','ja','雨が降ったら、家で映画を見ましょう。','如果下雨，就在家看电影吧。','条件或完成后；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"雨が降ったら、家で映画を見ましょう。","reading":"あめがふったら、いえでえいがをみましょう。"}]',NULL,'2'),
('35e1a-ge-ja-tara-03','ja-tara','ja','時間がなかったら、明日でも大丈夫です。','如果没时间，明天也可以。','条件或完成后；新增正式例句覆盖：negative / restriction。',NULL,'[{"text":"時間がなかったら、明日でも大丈夫です。","reading":"じかんがなかったら、あすでもだいじょうぶです。"}]',NULL,'3'),
('35e1a-ge-ja-tara-04','ja-tara','ja','薬を飲んでも治らなかったら、病院へ行ってください。','吃药也不好转的话，请去医院。','条件或完成后；新增正式例句覆盖：negative / restriction。',NULL,'[{"text":"薬を飲んでも治らなかったら、病院へ行ってください。","reading":"くすりをのんでもなおらなかったら、びょういんへいってください。"}]',NULL,'4');
INSERT INTO v2_grammar_examples(id,grammar_id,language,text,translation_zh,explanation_zh,ipa,readings_json,source_expression_id,sort_order) VALUES
('35e1a-ge-ja-tara-05','ja-tara','ja','仕事が終わったら、何をしますか。','工作结束后做什么？','条件或完成后；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"仕事が終わったら、何をしますか。","reading":"しごとがおわったら、なにをしますか。"}]',NULL,'5'),
('35e1a-ge-ja-tara-06','ja-tara','ja','もっと安かったら、買いたいです。','如果再便宜一点，我想买。','条件或完成后；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"もっと安かったら、買いたいです。","reading":"もっとやすかったら、かいたいです。"}]',NULL,'6'),
('35e1a-ge-ja-tara-07','ja-tara','ja','道に迷ったら、駅員に聞きます。','如果迷路，就问车站工作人员。','条件或完成后；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"道に迷ったら、駅員に聞きます。","reading":"みちにまよったら、えきいんにききます。"}]',NULL,'7'),
('35e1a-ge-ja-koto-ga-aru-01','ja-koto-ga-aru','ja','私は北海道へ行ったことがあります。','我去过北海道。','过去经历；新增正式例句覆盖：canonical/basic usage。',NULL,'[{"text":"私は北海道へ行ったことがあります。","reading":"わたしはほっかいどうへいったことがあります。"}]',NULL,'1'),
('35e1a-ge-ja-koto-ga-aru-02','ja-koto-ga-aru','ja','この料理を食べたことはありません。','我没吃过这道菜。','过去经历；新增正式例句覆盖：negative / restriction。',NULL,'[{"text":"この料理を食べたことはありません。","reading":"このりょうりをたべたことはありません。"}]',NULL,'2'),
('35e1a-ge-ja-koto-ga-aru-03','ja-koto-ga-aru','ja','一人で海外へ行ったことがありますか。','你一个人去过国外吗？','过去经历；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"一人で海外へ行ったことがありますか。","reading":"ひとりでかいがいへいったことがありますか。"}]',NULL,'3'),
('35e1a-ge-ja-koto-ga-aru-04','ja-koto-ga-aru','ja','電車の中に財布を忘れたことがあります。','我曾经把钱包忘在电车里。','过去经历；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"電車の中に財布を忘れたことがあります。","reading":"でんしゃのなかにさいふをわすれたことがあります。"}]',NULL,'4'),
('35e1a-ge-ja-koto-ga-aru-05','ja-koto-ga-aru','ja','彼とは前に会ったことがあります。','我以前见过他。','过去经历；新增正式例句覆盖：natural context with appropriate inflection/register。',NULL,'[{"text":"彼とは前に会ったことがあります。","reading":"かれとはまえにあったことがあります。"}]',NULL,'5'),
